import csv
import io
import re


def import_text(text, store, dry_run=False):
    # Phase 1: parse and validate every row before committing anything,
    # so a single invalid row leaves the store completely untouched.
    items = []
    for row in csv.DictReader(io.StringIO(text)):
        sku = (row['sku'] or '').strip()
        name = (row['name'] or '').strip()
        qty = (row['qty'] or '').strip()
        if not sku:
            raise ValueError('sku must not be empty')
        if not name:
            raise ValueError('name must not be empty')
        if re.fullmatch(r'[0-9]+', qty) is None:
            raise ValueError('qty must contain only decimal digits')
        items.append({'sku': sku, 'name': name, 'qty': int(qty)})

    # Phase 2: work out the result and (unless dry-run) commit each change.
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

